with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'الأرصاد المدارية والأعاصير المتقدمة','الدوران المداري والمونسون والموجات المدارية ونشوء الأعاصير وبنيتها وشدتها ومسارها وأخطارها.',55,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الدوران المداري والرياح الموسمية',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'ديناميكية الأعاصير المدارية',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('tropical-circulation-hadley-cell','دوران هادلي والدوران المداري','الخلايا المدارية ونقل الحرارة والزخم','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل دوران هادلي خلية واسعة تنقل الطاقة من المناطق المدارية نحو العروض الأعلى عبر صعود الهواء قرب نطاق التقارب المداري وهبوطه في شبه المدارية. يتغير موقع الخلية وقوتها موسمياً ويتفاعل مع دوران ووكر والرياح الموسمية."},{"type":"heading","text":"الحقول والبيانات اللازمة"},{"type":"text","text":"يتطلب تحليل دوران هادلي والدوران المداري دمج الضغط السطحي والرياح والدوامية والرطوبة والحرارة والقص الرأسي وبيانات المحيط وصور الأقمار والرادار عند توفرها. يجب توحيد زمن التحليل ومراعاة أن المؤشرات البيئية لا تمثل ضماناً لتطور الظاهرة."},{"type":"heading","text":"منهجية التشخيص"},{"type":"list","items":["حدد النطاق المداري والمرحلة الموسمية والبيئة واسعة النطاق.","حلل بنية الرياح والدوامية والرطوبة عبر طبقات متعددة.","افحص حرارة سطح البحر والمحتوى الحراري والقص الرأسي عند الحاجة.","تابع تطور النظام زمنياً ولا تعتمد على لقطة منفردة.","قارن المؤشرات بالرصد الفعلي والنماذج وبيّن عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة مدارية","text":"اختر حالة مدارية موثقة وطبق إطار دوران هادلي والدوران المداري على خرائط متعاقبة. اربط التغيرات في الحقول الجوية بالبنية السحابية والهطول، ثم افصل بين الإشارات المرصودة والتفسيرات المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل تغير موقع نطاق التقارب المداري بين موسمين واربطه بدوران هادلي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مؤشر بيئي منفرد دليلاً كافياً على تطور الإعصار.","الخلط بين حجم النظام وشدته.","إهمال تفاعل المحيط والقص الرأسي.","تفسير مسار الإعصار من ضغط سطحي فقط.","إغفال التغير السريع وعدم اليقين في التوقع."]},{"type":"callout","text":"في الأرصاد المدارية، التشخيص الموثوق يجمع بين البيئة واسعة النطاق والبنية الداخلية والرصد المتكرر، ويفصل بين المسار والشدة والأخطار."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح دوران هادلي والدوران المداري أن الأنظمة المدارية ناتجة عن تفاعل ديناميكي وحراري ومحيطي متعدد المقاييس، وأن تقييم أخطارها يتطلب متابعة شاملة."}]}'::jsonb,7160,55,'["شرح آليات دوران هادلي والدوران المداري","تحليل الحقول الجوية والبحرية المرتبطة","تقييم التطور وعدم اليقين والأخطار"]'::jsonb,'الدوران المداري والرياح الموسمية'),
('walker-circulation-dynamics','ديناميكية دوران ووكر','الدوران الشرقي-الغربي فوق المحيطات المدارية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ دوران ووكر من فروق التسخين بين أحواض المحيطات المدارية، ويظهر في حركة صاعدة فوق مناطق الحمل الواسع وهبوط فوق مناطق أخرى مع رياح سطحية عكسية. يتغير بقوة خلال ENSO."},{"type":"heading","text":"الحقول والبيانات اللازمة"},{"type":"text","text":"يتطلب تحليل ديناميكية دوران ووكر دمج الضغط السطحي والرياح والدوامية والرطوبة والحرارة والقص الرأسي وبيانات المحيط وصور الأقمار والرادار عند توفرها. يجب توحيد زمن التحليل ومراعاة أن المؤشرات البيئية لا تمثل ضماناً لتطور الظاهرة."},{"type":"heading","text":"منهجية التشخيص"},{"type":"list","items":["حدد النطاق المداري والمرحلة الموسمية والبيئة واسعة النطاق.","حلل بنية الرياح والدوامية والرطوبة عبر طبقات متعددة.","افحص حرارة سطح البحر والمحتوى الحراري والقص الرأسي عند الحاجة.","تابع تطور النظام زمنياً ولا تعتمد على لقطة منفردة.","قارن المؤشرات بالرصد الفعلي والنماذج وبيّن عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة مدارية","text":"اختر حالة مدارية موثقة وطبق إطار ديناميكية دوران ووكر على خرائط متعاقبة. اربط التغيرات في الحقول الجوية بالبنية السحابية والهطول، ثم افصل بين الإشارات المرصودة والتفسيرات المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اربط بين تغير حرارة سطح المحيط الهادئ وتغير مواقع الصعود والهبوط في دوران ووكر."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مؤشر بيئي منفرد دليلاً كافياً على تطور الإعصار.","الخلط بين حجم النظام وشدته.","إهمال تفاعل المحيط والقص الرأسي.","تفسير مسار الإعصار من ضغط سطحي فقط.","إغفال التغير السريع وعدم اليقين في التوقع."]},{"type":"callout","text":"في الأرصاد المدارية، التشخيص الموثوق يجمع بين البيئة واسعة النطاق والبنية الداخلية والرصد المتكرر، ويفصل بين المسار والشدة والأخطار."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح ديناميكية دوران ووكر أن الأنظمة المدارية ناتجة عن تفاعل ديناميكي وحراري ومحيطي متعدد المقاييس، وأن تقييم أخطارها يتطلب متابعة شاملة."}]}'::jsonb,7170,55,'["شرح آليات ديناميكية دوران ووكر","تحليل الحقول الجوية والبحرية المرتبطة","تقييم التطور وعدم اليقين والأخطار"]'::jsonb,'الدوران المداري والرياح الموسمية'),
('intertropical-convergence-zone','منطقة التقارب المدارية ITCZ','التقارب السطحي والحمل المطري المداري','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتحدد منطقة التقارب المدارية بتلاقي الرياح التجارية وصعود الهواء الرطب وتطور السحب العميقة. يتحرك نطاقها موسمياً وقد يتجزأ أو ينحرف عن خط الاستواء تبعاً لتوزيع اليابسة والبحر والدوران."},{"type":"heading","text":"الحقول والبيانات اللازمة"},{"type":"text","text":"يتطلب تحليل منطقة التقارب المدارية ITCZ دمج الضغط السطحي والرياح والدوامية والرطوبة والحرارة والقص الرأسي وبيانات المحيط وصور الأقمار والرادار عند توفرها. يجب توحيد زمن التحليل ومراعاة أن المؤشرات البيئية لا تمثل ضماناً لتطور الظاهرة."},{"type":"heading","text":"منهجية التشخيص"},{"type":"list","items":["حدد النطاق المداري والمرحلة الموسمية والبيئة واسعة النطاق.","حلل بنية الرياح والدوامية والرطوبة عبر طبقات متعددة.","افحص حرارة سطح البحر والمحتوى الحراري والقص الرأسي عند الحاجة.","تابع تطور النظام زمنياً ولا تعتمد على لقطة منفردة.","قارن المؤشرات بالرصد الفعلي والنماذج وبيّن عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة مدارية","text":"اختر حالة مدارية موثقة وطبق إطار منطقة التقارب المدارية ITCZ على خرائط متعاقبة. اربط التغيرات في الحقول الجوية بالبنية السحابية والهطول، ثم افصل بين الإشارات المرصودة والتفسيرات المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"استخرج نطاق ITCZ من خرائط الرياح والهطول وحدد التغير الموسمي."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مؤشر بيئي منفرد دليلاً كافياً على تطور الإعصار.","الخلط بين حجم النظام وشدته.","إهمال تفاعل المحيط والقص الرأسي.","تفسير مسار الإعصار من ضغط سطحي فقط.","إغفال التغير السريع وعدم اليقين في التوقع."]},{"type":"callout","text":"في الأرصاد المدارية، التشخيص الموثوق يجمع بين البيئة واسعة النطاق والبنية الداخلية والرصد المتكرر، ويفصل بين المسار والشدة والأخطار."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح منطقة التقارب المدارية ITCZ أن الأنظمة المدارية ناتجة عن تفاعل ديناميكي وحراري ومحيطي متعدد المقاييس، وأن تقييم أخطارها يتطلب متابعة شاملة."}]}'::jsonb,7180,55,'["شرح آليات منطقة التقارب المدارية ITCZ","تحليل الحقول الجوية والبحرية المرتبطة","تقييم التطور وعدم اليقين والأخطار"]'::jsonb,'الدوران المداري والرياح الموسمية'),
('tropical-easterly-waves','الموجات الشرقية المدارية','الاضطرابات الموجية ومناطق الحمل','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تنتقل الموجات الشرقية غرباً عبر المناطق المدارية وتسبب تغيرات دورية في الرياح والضغط والرطوبة والحمل. قد تسهم بعض الموجات في تنظيم الهطول أو تهيئة بيئة اضطراب مداري، لكن ليس كل موجة تتحول إلى إعصار."},{"type":"heading","text":"الحقول والبيانات اللازمة"},{"type":"text","text":"يتطلب تحليل الموجات الشرقية المدارية دمج الضغط السطحي والرياح والدوامية والرطوبة والحرارة والقص الرأسي وبيانات المحيط وصور الأقمار والرادار عند توفرها. يجب توحيد زمن التحليل ومراعاة أن المؤشرات البيئية لا تمثل ضماناً لتطور الظاهرة."},{"type":"heading","text":"منهجية التشخيص"},{"type":"list","items":["حدد النطاق المداري والمرحلة الموسمية والبيئة واسعة النطاق.","حلل بنية الرياح والدوامية والرطوبة عبر طبقات متعددة.","افحص حرارة سطح البحر والمحتوى الحراري والقص الرأسي عند الحاجة.","تابع تطور النظام زمنياً ولا تعتمد على لقطة منفردة.","قارن المؤشرات بالرصد الفعلي والنماذج وبيّن عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة مدارية","text":"اختر حالة مدارية موثقة وطبق إطار الموجات الشرقية المدارية على خرائط متعاقبة. اربط التغيرات في الحقول الجوية بالبنية السحابية والهطول، ثم افصل بين الإشارات المرصودة والتفسيرات المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"تتبع موجة شرقية عبر خرائط الرياح والرطوبة وحدد مراحل نشاط الحمل."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مؤشر بيئي منفرد دليلاً كافياً على تطور الإعصار.","الخلط بين حجم النظام وشدته.","إهمال تفاعل المحيط والقص الرأسي.","تفسير مسار الإعصار من ضغط سطحي فقط.","إغفال التغير السريع وعدم اليقين في التوقع."]},{"type":"callout","text":"في الأرصاد المدارية، التشخيص الموثوق يجمع بين البيئة واسعة النطاق والبنية الداخلية والرصد المتكرر، ويفصل بين المسار والشدة والأخطار."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح الموجات الشرقية المدارية أن الأنظمة المدارية ناتجة عن تفاعل ديناميكي وحراري ومحيطي متعدد المقاييس، وأن تقييم أخطارها يتطلب متابعة شاملة."}]}'::jsonb,7190,55,'["شرح آليات الموجات الشرقية المدارية","تحليل الحقول الجوية والبحرية المرتبطة","تقييم التطور وعدم اليقين والأخطار"]'::jsonb,'الدوران المداري والرياح الموسمية'),
('monsoon-trough-dynamics','ديناميكية أخدود الرياح الموسمية','التقارب والدوامية والحمل الموسمي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل أخدود الرياح الموسمية منطقة ضغط منخفض وتقارب ورياح رطبة، وقد يترافق مع اضطرابات واسعة وهطول غزير. يتغير موقعه وقوته مع تطور الموسم والتضاريس وحرارة المحيط."},{"type":"heading","text":"الحقول والبيانات اللازمة"},{"type":"text","text":"يتطلب تحليل ديناميكية أخدود الرياح الموسمية دمج الضغط السطحي والرياح والدوامية والرطوبة والحرارة والقص الرأسي وبيانات المحيط وصور الأقمار والرادار عند توفرها. يجب توحيد زمن التحليل ومراعاة أن المؤشرات البيئية لا تمثل ضماناً لتطور الظاهرة."},{"type":"heading","text":"منهجية التشخيص"},{"type":"list","items":["حدد النطاق المداري والمرحلة الموسمية والبيئة واسعة النطاق.","حلل بنية الرياح والدوامية والرطوبة عبر طبقات متعددة.","افحص حرارة سطح البحر والمحتوى الحراري والقص الرأسي عند الحاجة.","تابع تطور النظام زمنياً ولا تعتمد على لقطة منفردة.","قارن المؤشرات بالرصد الفعلي والنماذج وبيّن عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة مدارية","text":"اختر حالة مدارية موثقة وطبق إطار ديناميكية أخدود الرياح الموسمية على خرائط متعاقبة. اربط التغيرات في الحقول الجوية بالبنية السحابية والهطول، ثم افصل بين الإشارات المرصودة والتفسيرات المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن أخدوداً موسمياً نشطاً بمرحلة ضعف باستخدام الضغط والدوامية والهطول."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مؤشر بيئي منفرد دليلاً كافياً على تطور الإعصار.","الخلط بين حجم النظام وشدته.","إهمال تفاعل المحيط والقص الرأسي.","تفسير مسار الإعصار من ضغط سطحي فقط.","إغفال التغير السريع وعدم اليقين في التوقع."]},{"type":"callout","text":"في الأرصاد المدارية، التشخيص الموثوق يجمع بين البيئة واسعة النطاق والبنية الداخلية والرصد المتكرر، ويفصل بين المسار والشدة والأخطار."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح ديناميكية أخدود الرياح الموسمية أن الأنظمة المدارية ناتجة عن تفاعل ديناميكي وحراري ومحيطي متعدد المقاييس، وأن تقييم أخطارها يتطلب متابعة شاملة."}]}'::jsonb,7200,55,'["شرح آليات ديناميكية أخدود الرياح الموسمية","تحليل الحقول الجوية والبحرية المرتبطة","تقييم التطور وعدم اليقين والأخطار"]'::jsonb,'الدوران المداري والرياح الموسمية'),
('monsoon-onset-diagnostics','تشخيص بداية الرياح الموسمية','التحول الدوري في الرياح والهطول','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"لا يعتمد تحديد بداية الرياح الموسمية على أول عاصفة مطرية منفردة، بل على تحول مستمر في اتجاه الرياح والرطوبة والهطول والدوران واسع النطاق. تختلف المعايير بين الأقاليم."},{"type":"heading","text":"الحقول والبيانات اللازمة"},{"type":"text","text":"يتطلب تحليل تشخيص بداية الرياح الموسمية دمج الضغط السطحي والرياح والدوامية والرطوبة والحرارة والقص الرأسي وبيانات المحيط وصور الأقمار والرادار عند توفرها. يجب توحيد زمن التحليل ومراعاة أن المؤشرات البيئية لا تمثل ضماناً لتطور الظاهرة."},{"type":"heading","text":"منهجية التشخيص"},{"type":"list","items":["حدد النطاق المداري والمرحلة الموسمية والبيئة واسعة النطاق.","حلل بنية الرياح والدوامية والرطوبة عبر طبقات متعددة.","افحص حرارة سطح البحر والمحتوى الحراري والقص الرأسي عند الحاجة.","تابع تطور النظام زمنياً ولا تعتمد على لقطة منفردة.","قارن المؤشرات بالرصد الفعلي والنماذج وبيّن عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة مدارية","text":"اختر حالة مدارية موثقة وطبق إطار تشخيص بداية الرياح الموسمية على خرائط متعاقبة. اربط التغيرات في الحقول الجوية بالبنية السحابية والهطول، ثم افصل بين الإشارات المرصودة والتفسيرات المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صمم مجموعة مؤشرات لتحديد بداية موسمية موثوقة بدلاً من حدث مطري عابر."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مؤشر بيئي منفرد دليلاً كافياً على تطور الإعصار.","الخلط بين حجم النظام وشدته.","إهمال تفاعل المحيط والقص الرأسي.","تفسير مسار الإعصار من ضغط سطحي فقط.","إغفال التغير السريع وعدم اليقين في التوقع."]},{"type":"callout","text":"في الأرصاد المدارية، التشخيص الموثوق يجمع بين البيئة واسعة النطاق والبنية الداخلية والرصد المتكرر، ويفصل بين المسار والشدة والأخطار."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح تشخيص بداية الرياح الموسمية أن الأنظمة المدارية ناتجة عن تفاعل ديناميكي وحراري ومحيطي متعدد المقاييس، وأن تقييم أخطارها يتطلب متابعة شاملة."}]}'::jsonb,7210,55,'["شرح آليات تشخيص بداية الرياح الموسمية","تحليل الحقول الجوية والبحرية المرتبطة","تقييم التطور وعدم اليقين والأخطار"]'::jsonb,'الدوران المداري والرياح الموسمية'),
('monsoon-break-circulation','فترات انقطاع نشاط المونسون','تغير محور المطر والدوران','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تشير فترات الانقطاع إلى تراجع الهطول في بعض مناطق المونسون نتيجة تغير موقع أخدود المونسون أو إعادة تنظيم الدوران. قد تنتقل الأمطار إلى مناطق أخرى بدلاً من اختفاء النشاط المداري كلياً."},{"type":"heading","text":"الحقول والبيانات اللازمة"},{"type":"text","text":"يتطلب تحليل فترات انقطاع نشاط المونسون دمج الضغط السطحي والرياح والدوامية والرطوبة والحرارة والقص الرأسي وبيانات المحيط وصور الأقمار والرادار عند توفرها. يجب توحيد زمن التحليل ومراعاة أن المؤشرات البيئية لا تمثل ضماناً لتطور الظاهرة."},{"type":"heading","text":"منهجية التشخيص"},{"type":"list","items":["حدد النطاق المداري والمرحلة الموسمية والبيئة واسعة النطاق.","حلل بنية الرياح والدوامية والرطوبة عبر طبقات متعددة.","افحص حرارة سطح البحر والمحتوى الحراري والقص الرأسي عند الحاجة.","تابع تطور النظام زمنياً ولا تعتمد على لقطة منفردة.","قارن المؤشرات بالرصد الفعلي والنماذج وبيّن عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة مدارية","text":"اختر حالة مدارية موثقة وطبق إطار فترات انقطاع نشاط المونسون على خرائط متعاقبة. اربط التغيرات في الحقول الجوية بالبنية السحابية والهطول، ثم افصل بين الإشارات المرصودة والتفسيرات المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل انتقال نطاق الهطول خلال فترة انقطاع موسمية باستخدام خرائط يومية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مؤشر بيئي منفرد دليلاً كافياً على تطور الإعصار.","الخلط بين حجم النظام وشدته.","إهمال تفاعل المحيط والقص الرأسي.","تفسير مسار الإعصار من ضغط سطحي فقط.","إغفال التغير السريع وعدم اليقين في التوقع."]},{"type":"callout","text":"في الأرصاد المدارية، التشخيص الموثوق يجمع بين البيئة واسعة النطاق والبنية الداخلية والرصد المتكرر، ويفصل بين المسار والشدة والأخطار."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح فترات انقطاع نشاط المونسون أن الأنظمة المدارية ناتجة عن تفاعل ديناميكي وحراري ومحيطي متعدد المقاييس، وأن تقييم أخطارها يتطلب متابعة شاملة."}]}'::jsonb,7220,55,'["شرح آليات فترات انقطاع نشاط المونسون","تحليل الحقول الجوية والبحرية المرتبطة","تقييم التطور وعدم اليقين والأخطار"]'::jsonb,'الدوران المداري والرياح الموسمية'),
('tropical-upper-tropospheric-trough','أخدود التروبوسفير العلوي المداري','الرياح العليا والقص والحمل العميق','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل أخدود التروبوسفير العلوي المداري بنية واسعة في الدوران العلوي تؤثر في القص الرأسي والتهوية والحمل المداري. قد يعزز أو يثبط تطور الاضطرابات بحسب موقعه وتفاعله مع الرطوبة."},{"type":"heading","text":"الحقول والبيانات اللازمة"},{"type":"text","text":"يتطلب تحليل أخدود التروبوسفير العلوي المداري دمج الضغط السطحي والرياح والدوامية والرطوبة والحرارة والقص الرأسي وبيانات المحيط وصور الأقمار والرادار عند توفرها. يجب توحيد زمن التحليل ومراعاة أن المؤشرات البيئية لا تمثل ضماناً لتطور الظاهرة."},{"type":"heading","text":"منهجية التشخيص"},{"type":"list","items":["حدد النطاق المداري والمرحلة الموسمية والبيئة واسعة النطاق.","حلل بنية الرياح والدوامية والرطوبة عبر طبقات متعددة.","افحص حرارة سطح البحر والمحتوى الحراري والقص الرأسي عند الحاجة.","تابع تطور النظام زمنياً ولا تعتمد على لقطة منفردة.","قارن المؤشرات بالرصد الفعلي والنماذج وبيّن عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تحليل حالة مدارية","text":"اختر حالة مدارية موثقة وطبق إطار أخدود التروبوسفير العلوي المداري على خرائط متعاقبة. اربط التغيرات في الحقول الجوية بالبنية السحابية والهطول، ثم افصل بين الإشارات المرصودة والتفسيرات المحتملة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"افحص علاقة أخدود علوي مداري ببيئة اضطراب مداري باستخدام خرائط الرياح والقص."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["اعتبار مؤشر بيئي منفرد دليلاً كافياً على تطور الإعصار.","الخلط بين حجم النظام وشدته.","إهمال تفاعل المحيط والقص الرأسي.","تفسير مسار الإعصار من ضغط سطحي فقط.","إغفال التغير السريع وعدم اليقين في التوقع."]},{"type":"callout","text":"في الأرصاد المدارية، التشخيص الموثوق يجمع بين البيئة واسعة النطاق والبنية الداخلية والرصد المتكرر، ويفصل بين المسار والشدة والأخطار."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"يوضح أخدود التروبوسفير العلوي المداري أن الأنظمة المدارية ناتجة عن تفاعل ديناميكي وحراري ومحيطي متعدد المقاييس، وأن تقييم أخطارها يتطلب متابعة شاملة."}]}'::jsonb,7230,55,'["شرح آليات أخدود التروبوسفير العلوي المداري","تحليل الحقول الجوية والبحرية المرتبطة","تقييم التطور وعدم اليقين والأخطار"]'::jsonb,'الدوران المداري والرياح الموسمية'),
